 const card=n=>{const T=TONE[n];return`<a class="hcard tcard" href="#tone-${toneSlug(n)}"><span class="eyebrow">${esc(TONE_INST[T.inst]||T.inst)}${T.custom?' · researched':''}</span><b>${esc(n)}</b>${eqSVG(T.eq,{small:true})}<span class="hint">${esc(T.sig)}</span></a>`};
 const researchBox=n=>`<div class="lookup"><p><b>${esc(n)}</b> doesn't have a tone guide yet.</p><p class="hint">Claude can research their gear, settings and recording style as a ${TONE_INST[inst].toLowerCase()} player. Change the tab above if they play something else.</p><button class="btn primary" id="trgo">Research ${esc(n)}'s tone</button></div>`;
